sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here

    var user = current.resource;

    var userData = new GlideAggregate("x_1324635_grc_ops_milestones");
    userData.addAggregate('COUNT', 'type');
    userData.addEncodedQuery("resource=" + user);
    userData.query();
    var milestoneData = {
        "accelerator": "0",
        "certification": "0",
        "project_feedback": "0"
    };
    while (userData.next()) {
        milestoneData[userData.type] = userData.getAggregate('COUNT', 'type');
    }

    var role = "";

    if (isUserInGroup(user, 'GRC Interns')) {
        role = "x_1324635_grc_ops.grc_interns";
    } else if (isUserInGroup(user, 'GRC Associates')) {
        role = "x_1324635_grc_ops.grc_assoc";
    } else if (isUserInGroup(user, 'GRC Senior Associates')) {
        role = "x_1324635_grc_ops.grc_sen_assoc";
    } else if (isUserInGroup(user, 'GRC Managers')) {
        role = "x_1324635_grc_ops.grc_mgr";
    }


    var complianceMatric = getPerformanceMatrix(role);

    var complianceScore = calculateCompliance(milestoneData, complianceMatric);

    function getPerformanceMatrix(userrole) {
        var inputs = {};
        inputs['u_role'] = userrole; // Choice 

        var dt = new sn_dt.DecisionTableAPI();
        var response = dt.getDecision('a93d96298346f61002d6c3b6feaad38e', inputs);

        var result_elements = response.result_elements;
        var u_certificate = result_elements.u_certificate.getValue(); // Integer
        var u_pod_activities = result_elements.u_pod_activities.getValue(); // Integer
        var u_accelarator = result_elements.u_accelarator.getValue(); // Integer
        var u_project_feedback = result_elements.u_project_feedback.getValue(); // Integer

        var matric = {};
        matric.certificate = Number(u_certificate);
        matric.pod = Number(u_pod_activities);
        matric.accelarator = Number(u_accelarator);
        matric.project_feedback = Number(u_pod_activities);

        return matric;
    }

    function calculateCompliance(userMatric, requiredMatric) {


        if (requiredMatric.certificate == "") {
            requiredMatric.certificate = 1;
        }
        if (requiredMatric.pod + requiredMatric.accelarator == "") {
            requiredMatric.accelarator = 1;
        }
        if (requiredMatric.project_feedback == "") {
            requiredMatric.project_feedback = 1;
        }
        var certificateCompliance = (userMatric.certification / requiredMatric.certificate) * 100;
        var podCompliance = (userMatric.accelerator / (requiredMatric.pod + requiredMatric.accelarator)) * 100;
        var projectCompliance = (userMatric.project_feedback / requiredMatric.project_feedback) * 100;
        if (certificateCompliance > 100) {
            certificateCompliance = 100;
        }
        if (podCompliance > 100) {
            podCompliance = 100;
        }
        if (projectCompliance > 100) {
            projectCompliance = 100;
        }
        var totalCompliance = (certificateCompliance + podCompliance + projectCompliance) / 3;
        return Math.round(totalCompliance);
    }

    function isUserInGroup(userSysId, groupname) {
        var group = new GlideRecord('sys_user_grmember');
        group.addEncodedQuery("group.name=" + groupname + "^user=" + userSysId);
        group.query();

        // If a record is found, the user is a member of the group
        return group.next();
    }

    var userRecord = new GlideRecord("sys_user");
    userRecord.addEncodedQuery("sys_id=" + user);
    userRecord.query();

    if (userRecord.next()) {
       // gs.info(userRecord.name + "'s compliant score =" + complianceScore);
        userRecord.x_1324635_grc_ops_compliance_score = complianceScore;
        userRecord.update();
    }

})(current, previous);
